package decimal

import (
	"math/big"
	"testing"
)

func rat(t *testing.T, s string) *big.Rat {
	t.Helper()
	r, ok := new(big.Rat).SetString(s)
	if !ok {
		t.Fatalf("bad rational literal %q", s)
	}
	return r
}

func TestFormatTwoDecimals(t *testing.T) {
	cases := map[string]string{
		"3":          "3.00",
		"0":          "0.00",
		"1234567.89": "1234567.89",
		"0.5":        "0.50",
		"-3":         "-3.00",
		"100.1":      "100.10",
